        i = verb_idx + 1
        if i < len(tokens) and tokens[i] == "around":
            around = True
            i += 1
        if i < len(tokens) and tokens[i] == "opposite":
            opposite = True
            i += 1
        if i < len(tokens) and tokens[i] in dirs:
            direction = tokens[i]

        # build one unit (no multiplicity)
        unit = []
        if direction:
            if around:
                for _ in range(4):
                    unit.append(f"I_TURN_{direction.upper()}")
                    unit.append(f"I_{verb.upper()}")
            else:
                turn_cnt = 2 if opposite else 1
                for _ in range(turn_cnt):
                    unit.append(f"I_TURN_{direction.upper()}")
                unit.append(f"I_{verb.upper()}")
        else:
            unit.append(f"I_{verb.upper()}")

        # apply multiplicity
        return unit * repeat

